// Original images remain authoritative. Search and region marks do not change learning evidence.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function searchCourse(data,query,topic_id=null){const q=query.trim().toLowerCase();if(!q)return [];const out=[];for(const t of data.course.topics.filter(t=>!topic_id||t.topic_id===topic_id)){const add=(kind,text,anchor,label)=>{if(text?.toLowerCase().includes(q))out.push({topic_id:t.topic_id,kind,text,anchor,label});};add('标题',t.title,'learning-goals',t.title);for(const r of data.readings.filter(r=>t.reading_refs.includes(r.content_id)))add('正文',r.text_for_search,'source-'+r.content_id,'印刷页 '+r.printed_page);for(const f of data.figures.filter(f=>f.reading_refs.some(id=>t.reading_refs.includes(id))))add('图注',f.caption,'source-'+f.reading_refs.find(id=>t.reading_refs.includes(id)),'Figure '+f.figure_number);for(const s of data.supplements.filter(s=>t.supplement_refs.includes(s.supplement_id)))add('补充',s.title+' '+s.notes.join(' ')+' '+s.formulas.join(' '),'supplements',s.title);for(const e of data.exercises.filter(e=>t.exercise_refs.includes(e.exercise_id)))add('习题',e.question_text,e.exercise_id,'习题 '+e.source_number);}return out;}
export function snippet(text,query){const i=text.toLowerCase().indexOf(query.toLowerCase());if(i<0)return esc(text.slice(0,140));return (i>35?'…':'')+esc(text.slice(Math.max(0,i-35),i))+'<mark>'+esc(text.slice(i,i+query.length))+'</mark>'+esc(text.slice(i+query.length,i+query.length+90))+(text.length>i+query.length+90?'…':'');}
function modal(title,html){document.getElementById('pl-reader-dialog')?.remove();const d=document.createElement('dialog');d.id='pl-reader-dialog';d.className='reader-dialog';d.setAttribute('aria-label',title);d.innerHTML=`<div class="reader-dialog-head"><h2>${esc(title)}</h2><button class="ghost-btn" data-close>关闭</button></div>${html}`;document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.showModal();return d;}
export async function attachReader({topic_id,course_id,openTopic}){
 const body=document.getElementById('topic-body'),toolbar=document.querySelector('.topic-toolbar');if(!body||!toolbar||document.getElementById('reader-search'))return;
 let store=await LearningStore.getModule('pl-reader-v1')||{marks:[],positions:{}};store.marks??=[];store.positions??={};if(!body.isConnected)return;
 const data=window.PathlineTextbook,scope=course_id+'|'+topic_id,topic=data.course.topics.find(t=>t.topic_id===topic_id),readings=data.readings.filter(r=>topic.reading_refs.includes(r.content_id));
 async function persist({content_id,mark,position}={}){store=await LearningStore.atomicModule('pl-reader-v1',prior=>{const value={marks:[],positions:{},...prior};value.marks??=[];value.positions??={};if(content_id){value.marks=value.marks.filter(m=>!(m.course_id===course_id&&m.content_id===content_id));if(mark)value.marks.push(mark);}if(position)value.positions[scope]=position;return {value};});}
 function paint(){for(const r of readings){const el=document.getElementById('source-'+r.content_id),mark=store.marks.find(m=>m.course_id===course_id&&m.content_id===r.content_id);if(!el)continue;el.classList.add('reader-region');el.dataset.markColor=mark?.color||'';el.querySelector('[data-region-note]')?.remove();if(mark?.note)el.insertAdjacentHTML('beforeend',`<p data-region-note>${esc(mark.note)}</p>`);}}
 function jump(anchor){const pane=document.getElementById('topic-body'),el=document.getElementById(anchor)||pane.querySelector(`[data-exercise-id="${CSS.escape(anchor)}"]`);if(!el)return;pane.dataset.readerJump='1';if(el.tagName==='DETAILS')el.open=true;el.scrollIntoView({block:'start'});el.classList.add('reader-match');setTimeout(()=>el.classList.remove('reader-match'),3000);}
 toolbar.insertAdjacentHTML('afterbegin','<button class="btn secondary small" id="reader-search">检索</button><button class="btn secondary small" id="reader-marks">标注</button>');
 document.getElementById('reader-search').onclick=()=>{const d=modal('检索教材','<form><label>关键词<input name="query" aria-label="检索关键词" required maxlength="200"></label><label>范围<select name="scope"><option value="topic">当前 Topic</option><option value="course">全课程</option></select></label><button class="btn accent">查找</button></form><p data-search-status role="status"></p><div data-search-results></div>');d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),q=f.get('query').trim(),status=d.querySelector('[data-search-status]'),out=d.querySelector('[data-search-results]'),submit=e.target.querySelector('button');if(!q)return;submit.disabled=true;status.textContent='正在检索…';try{if(f.get('scope')==='course')await ContentRuntime.ensure();const matches=searchCourse(data,q,f.get('scope')==='topic'?topic_id:null);status.textContent=`找到 ${matches.length} 处${matches.length>60?'，先显示前 60 处':''}。`;out.innerHTML=['标题','正文','图注','补充','习题'].map(kind=>{const rows=matches.slice(0,60).map((m,i)=>({...m,i})).filter(m=>m.kind===kind);return rows.length?`<h3>${kind}</h3>${rows.map(m=>`<button class="reader-result" data-result="${m.i}"><b>Topic ${esc(m.topic_id)} · ${esc(m.label)}</b><span>${snippet(m.text,q)}</span></button>`).join('')}`:'';}).join('');out.querySelectorAll('[data-result]').forEach(b=>b.onclick=async()=>{const m=matches[Number(b.dataset.result)];d.close();if(m.topic_id!==topic_id)await openTopic(m.topic_id);jump(m.anchor);});}catch{status.textContent='检索未完成。请联网后重试。';}finally{submit.disabled=false;}};};
 function stopSelecting(){body.querySelectorAll('[data-mark-region]').forEach(b=>b.remove());document.getElementById('reader-mark-mode')?.remove();}
 function editRegion(content_id){const old=store.marks.find(m=>m.course_id===course_id&&m.content_id===content_id),r=readings.find(r=>r.content_id===content_id),d=modal('标注正文区域',`<form><p>印刷页 ${r.printed_page} · OpenStax §${esc(r.source_section)}</p><label>颜色<select name="color"><option value="amber">浅黄</option><option value="sage">浅绿</option><option value="violet">浅紫</option></select></label><label>笔记（可选）<textarea name="note" maxlength="2000">${esc(old?.note||'')}</textarea></label><p data-error role="alert"></p><button class="btn accent">保存标注</button>${old?'<button type="button" class="ghost-btn" data-remove>移除标注</button>':''}</form>`);d.querySelector('select').value=old?.color||'amber';let saving=false;async function save(remove){if(saving)return;saving=true;try{const f=new FormData(d.querySelector('form')),mark=remove?null:{course_id,topic_id,content_id,color:f.get('color'),note:f.get('note'),printed_page:r.printed_page};await persist({content_id,mark});stopSelecting();paint();d.close();}catch{d.querySelector('[data-error]').textContent='标注未保存，请重试。';}finally{saving=false;}}d.querySelector('form').onsubmit=e=>{e.preventDefault();save(false);};d.querySelector('[data-remove]')?.addEventListener('click',()=>save(true));}
 document.getElementById('reader-marks').onclick=()=>{const marks=store.marks.filter(m=>m.course_id===course_id&&readings.some(r=>r.content_id===m.content_id)),d=modal('本节标注',`<button class="btn accent" data-select-region>选择正文区域</button><p class="tiny">原文以图像保真显示，标注保存到正文区域。</p>${marks.map((m,i)=>`<button class="reader-result" data-mark="${i}"><b>印刷页 ${m.printed_page}</b><span>${esc(m.note||'已标记')}</span></button>`).join('')||'<p>本节还没有标注。</p>'}`);d.querySelector('[data-select-region]').onclick=()=>{d.close();stopSelecting();toolbar.insertAdjacentHTML('beforeend','<button class="ghost-btn" id="reader-mark-mode">完成标注</button>');document.getElementById('reader-mark-mode').onclick=stopSelecting;for(const r of readings)document.getElementById('source-'+r.content_id)?.insertAdjacentHTML('afterbegin',`<button class="btn secondary small" data-mark-region="${esc(r.content_id)}">标注此段 · 印刷页 ${r.printed_page}</button>`);body.querySelectorAll('[data-mark-region]').forEach(b=>b.onclick=()=>editRegion(b.dataset.markRegion));};d.querySelectorAll('[data-mark]').forEach(b=>b.onclick=()=>{const m=marks[Number(b.dataset.mark)];d.close();jump('source-'+m.content_id);editRegion(m.content_id);});};
 paint();const saved=store.positions[scope];if(saved&&!body.dataset.readerJump&&document.getElementById(saved))document.getElementById(saved).scrollIntoView({block:'start'});
 let pending;body.addEventListener('scroll',()=>{clearTimeout(pending);pending=setTimeout(()=>{if(!body.isConnected)return;const top=body.getBoundingClientRect().top,closest=readings.map(r=>document.getElementById('source-'+r.content_id)).filter(Boolean).filter(el=>el.getBoundingClientRect().top<=top+body.clientHeight/2).at(-1);if(closest)persist({position:closest.id}).catch(()=>{});},600);},{passive:true});
}
